|group#visual| "V2 · Two responsibilities" { layout: flow; direction: column; gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "Library · browser-compatible" { width: 240; } [
    |cell#detail| "Read a document. Register vocabulary.\nInspect and compare declarations. No\nauthentication or business writes."
  ]
  |box#n2| "Explicit interpretation" { width: 240; } [
    |cell#detail| "Compile supported rules/selectors.\nEvaluate rules only with supplied\nstate. This is separate from\ninspection."
  ]
  |box#n3| "Consumer · host-only" { width: 240; } [
    |cell#detail| "Authenticate principal and service.\nAuthorize. Freeze identities. Execute\nand verify under the native\ntransaction boundary."
  ]
  |box#n4| "Qualification boundary" { width: 240; } [
    |cell#detail| "Declared compatibility is not\nexecution verification. Inspection\ndoes not invoke the consumer or access\nstorage."
  ]
]
